// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.concurrent.TimeUnit;
import java.util.function.BooleanSupplier;

/**
 * Drives a store's applier one unit at a time from a test. The applier is paused at a unit boundary, builds and
 * compactions are requested, their workers are allowed to finish, and the units that would publish the results stay in
 * the inbox until the test steps them. Commits made meanwhile only reach the commit log, which is the hold point every
 * interleaving test needs.
 */
final class ApplierStepping {

	private ApplierStepping() {
	}

	/** Pauses the applier and requests a rebuild without running any unit: the build has not pinned yet. */
	static void holdBuildBeforePin(LmdbDirectAdjacencyStore store) {
		store.pauseApplierForTest(true);
		store.requestRebuild();
	}

	/**
	 * Pauses the applier, requests a rebuild, lets the build worker run to completion and leaves its candidate in the
	 * inbox: the base is scanned, nothing is published yet, and a commit made now lands above the pin.
	 */
	static void holdBuildAfterScan(LmdbDirectAdjacencyStore store) {
		store.pauseApplierForTest(true);
		store.requestRebuild();
		stepUntil(store, store::buildInFlightForTest, "the build was submitted to a worker");
		assertThat(store.awaitWorkersIdleForTest(60, TimeUnit.SECONDS)).as("the build worker finished").isTrue();
	}

	/** Steps the applier until the held build is consumed, then lets the applier run again. */
	static void releaseBuild(LmdbDirectAdjacencyStore store) {
		stepUntil(store, () -> !store.buildInFlightForTest(), "the build candidate was consumed");
		store.pauseApplierForTest(false);
	}

	/**
	 * Steps the paused applier until the condition holds, waiting for the workers whenever the applier has no unit to
	 * run. Units other than the one a test cares about may be queued ahead of it; stepping past them keeps the test
	 * about the effect, not about inbox order.
	 */
	static void stepUntil(LmdbDirectAdjacencyStore store, BooleanSupplier condition, String description) {
		for (int steps = 0; steps < 200 && !condition.getAsBoolean(); steps++) {
			if (!store.stepApplierForTest()) {
				assertThat(store.awaitWorkersIdleForTest(60, TimeUnit.SECONDS)).as("workers idle: %s", description)
						.isTrue();
				if (!condition.getAsBoolean() && !store.stepApplierForTest()) {
					// nothing queued and no worker running: only time can change the condition now
					try {
						Thread.sleep(5);
					} catch (InterruptedException e) {
						Thread.currentThread().interrupt();
						throw new AssertionError(e);
					}
				}
			}
		}
		assertThat(condition.getAsBoolean()).as(description).isTrue();
	}

	/** Polls until the condition holds or the timeout passes. */
	static boolean awaitCondition(BooleanSupplier condition, long timeout, TimeUnit unit) {
		long deadline = System.nanoTime() + unit.toNanos(timeout);
		while (!condition.getAsBoolean()) {
			if (System.nanoTime() > deadline) {
				return false;
			}
			Thread.onSpinWait();
		}
		return true;
	}
}
